%% Plot histogram of nucleus area of all segmented nuclei for all datasets except chr17 datasets

clear all

% Load the .mat file with info about all segmented nuclei
parsed_data_dir = '/Users/nicolacrosetto/Library/CloudStorage/OneDrive-KarolinskaInstitutet/KI/Manuscripts/Li Wang et al_FOLD-FISH/FIRST SUBMISSION/Analyses/Image analyses/Parsed datasets';
load([parsed_data_dir, '/all_seg_nuc_data.mat']);

% Specify folder where plots should be stored
store_figs_dir = '/Users/nicolacrosetto/Library/CloudStorage/OneDrive-KarolinskaInstitutet/KI/Manuscripts/Li Wang et al_FOLD-FISH/FIRST SUBMISSION/Analyses/Image analyses/Plots';

% Loop through each dataset and plot histogram of nuc_area in a matrix plot
num_datasets = numel(all_seg_nuc.dataset);

for k = 1:num_datasets
        
    % Plot histogram of nucleus areas for the k-th dataset
    subplot(ceil(num_datasets/3), 3, k); % Create a subplot for each dataset
    [counts, edges] = histcounts(all_seg_nuc.area{k}, 'BinEdges', 25:5:100); % Set bin edges from 25 to 100 with reduced bin width
    hold on;
    % Smoothen the histogram line
    bin_centers = edges(1:end-1) + diff(edges)/2; % Calculate bin centers
    smooth_counts = smoothdata(counts, 'gaussian', 3); % Smooth the counts
    plot(bin_centers, smooth_counts / sum(smooth_counts) * (edges(2) - edges(1)), 'r-', 'LineWidth', 2); % Plot smoothened line
    hold off;
    xlabel('Nucleus Area (um^2)');
    ylabel('Probability Density');
    title(['Dataset: ', all_seg_nuc.dataset{k}], 'Interpreter', 'none');
    xlim([25 100]);
    ylim([0 1]);
    all_seg_nuc_num = numel(all_seg_nuc.area{k}); % Get the number of nuclei
    text(0.95, 0.95, sprintf('n = %d', all_seg_nuc_num), 'Units', 'normalized', ...
        'HorizontalAlignment', 'right', 'VerticalAlignment', 'top', 'FontSize', 10);
end

% Adjust layout to prevent overlap
sgtitle('Histogram of Nucleus Area for Each Dataset');
print(gcf, fullfile(store_figs_dir, 'nuc_area_histograms'), '-dpdf');  % Save figure as PDF

close all


%% Plot histograms of dot counts per nucleus for all datasets except chr17 datasets

clear all

% Load all relevant data
parsed_data_dir = '/Users/nicolacrosetto/Library/CloudStorage/OneDrive-KarolinskaInstitutet/KI/Manuscripts/Li Wang et al_FOLD-FISH/FIRST SUBMISSION/Analyses/Image analyses/Parsed datasets';
files = dir(fullfile(parsed_data_dir, '*__seg_nuc_data.mat'));

load([parsed_data_dir, '/all_seg_nuc_data.mat']); % Load the .mat file with info about all segmented nuclei

% Specify folder where plots should be stored
store_figs_dir = '/Users/nicolacrosetto/Library/CloudStorage/OneDrive-KarolinskaInstitutet/KI/Manuscripts/Li Wang et al_FOLD-FISH/FIRST SUBMISSION/Analyses/Image analyses/Plots';

% Loop through each dataset and plot dot counts and mean dot contrast per segmented nucleus
for k = 1:numel(files)

    load([parsed_data_dir, '/', files(k).name]); % Load the corresponding .mat file

    %Extract dataset ID and find its index in all_seg_nuc_data.mat
    idx = strfind(files(k).name, '_'); %Find index of underscores
    dataset_id = files(k).name(1:idx(1)-1);
    dataset_idx = find(strcmp(all_seg_nuc.dataset, dataset_id));
   
    % Plot fraction of segmented nuclei with 0,1,2,3,4,>4 dots
    figure(1)
    all_seg_nuc_num = all_seg_nuc.counts(dataset_idx);

    seg_nuc_with_dots_num = numel(seg_nuc_data.dot_counts);
    seg_nuc_1to4dots_num = nnz(seg_nuc_data.dot_counts == 1) + ...
                             nnz(seg_nuc_data.dot_counts == 2) + ...
                             nnz(seg_nuc_data.dot_counts == 3) + ...
                             nnz(seg_nuc_data.dot_counts == 4);

    perc_seg_nuc(1) = (all_seg_nuc_num - seg_nuc_with_dots_num) / (all_seg_nuc_num) * 100; % Fraction of segmented nuclei with 0 dots
    perc_seg_nuc(2) = nnz(seg_nuc_data.dot_counts == 1) / (all_seg_nuc_num) * 100;
    perc_seg_nuc(3) = nnz(seg_nuc_data.dot_counts == 2) / (all_seg_nuc_num) * 100;
    perc_seg_nuc(4) = nnz(seg_nuc_data.dot_counts == 3) / (all_seg_nuc_num) * 100;
    perc_seg_nuc(5) = nnz(seg_nuc_data.dot_counts == 4) / (all_seg_nuc_num) * 100;
    perc_seg_nuc(6) = nnz(seg_nuc_data.dot_counts > 4) / (all_seg_nuc_num) * 100;
    bar(perc_seg_nuc);
    xlabel('# of dots');
    ylabel('% of nuclei');
    title(files(k).name,'interpreter', 'none');
    set(gca, 'XTickLabel', {'0', '1', '2', '3', '4', '>4'});
    text(0.95, 0.95, sprintf('# of segm nuclei: %d', all_seg_nuc_num), 'Units', 'normalized', ...
        'HorizontalAlignment', 'right', 'VerticalAlignment', 'top', 'FontSize', 10);
    text(0.95, 0.90, sprintf('# of nuclei with 1-4 dots: %d', seg_nuc_1to4dots_num), 'Units', 'normalized', ...
        'HorizontalAlignment', 'right', 'VerticalAlignment', 'top', 'FontSize', 10);
    baseFileName = erase(files(k).name, '.mat');    % Remove .mat from file name for saving figures
    print(figure(1), fullfile(store_figs_dir, [baseFileName,'_dot_counts']), '-dpdf');  % Save figure as PDF

