%% Calculate and plot various properties of chr17 CTs for iiXZ1126 dataset

clear all

%Specify dataset to analyse
dataset_name = 'iiXZ1126_20250210_002_dw_A594_A647_cwdots_clusters_20251013';

%Specify folder where figures should be stored
store_figs_dir = '/Users/nicolacrosetto/Library/CloudStorage/OneDrive-KarolinskaInstitutet/KI/Manuscripts/Li Wang et al_FOLD-FISH/FIRST SUBMISSION/Analyses/Image analyses/Plots';

% Load the .mat files with info about chr17 clusters
parsed_data_dir = '/Users/nicolacrosetto/Library/CloudStorage/OneDrive-KarolinskaInstitutet/KI/Manuscripts/Li Wang et al_FOLD-FISH//FIRST SUBMISSION/Analyses/Image analyses/Parsed datasets';
load([parsed_data_dir, '/', dataset_name, '__seg_nuc_data.mat']);

seg_nuc_num = seg_nuc_data.seg_nuc_num; % # of segmented nuclei with dots in either A594 or A647 or both channels

a594_clust_num = 1; % Counter of A594 clusters with > 4 dots (min required to calculate the cluster convex hull)
a594_seg_nuc_2clust_num = 1; % Counter of nuclei with 2 A594 clusters with > 4 dots

a647_clust_num = 1; % Counter of A647 clusters with > 4 dots (min required to calculate the cluster convex hull)
a647_seg_nuc_2clust_num = 1; % Counter of nuclei with 2 A647 clusters with > 4 dots

%Loop through nuclei, count number of clusters and calculate convex hull volume of each cluster in each channel
for i= 1:seg_nuc_num
    
    %A594 dots
    if seg_nuc_data.a594_dot_counts(i) > 0 %Check if i-th nucleus contains dots in A594
        a594_seg_nuc_clust_num(i,1) = max(seg_nuc_data.a594_cluster_id(seg_nuc_data.a594_nuc_id == i)); % # of A594 clusters in i-th nucleus

        %Calculate convex hull volume (in um^3) of clusters with > 3 dots in each channel
        if a594_seg_nuc_clust_num(i,1) > 0
            for j = 1:a594_seg_nuc_clust_num(i,1)
                a594_dot_in_clust_coord = seg_nuc_data.a594_dot_coord(seg_nuc_data.a594_nuc_id == i & seg_nuc_data.a594_cluster_id == j,1:3);
                if height(a594_dot_in_clust_coord) > 3
                    [~,a594_clust_hull_vol(a594_clust_num,1)] = convhulln(a594_dot_in_clust_coord); % Calculate convex hull volume
                    a594_clust_num = a594_clust_num + 1;
                end
            end
        end

        %Calculate difference in convex hull vol between clusters for nuclei with 2 clusters
        if a594_seg_nuc_clust_num(i,1) == 2
            a594_clust1_dot_coord = seg_nuc_data.a594_dot_coord(seg_nuc_data.a594_nuc_id == i & seg_nuc_data.a594_cluster_id == 1,1:3);
            a594_clust2_dot_coord = seg_nuc_data.a594_dot_coord(seg_nuc_data.a594_nuc_id == i & seg_nuc_data.a594_cluster_id == 2,1:3);
            if height(a594_clust1_dot_coord) > 3 && height(a594_clust2_dot_coord) > 3
                [~,a594_clust1_hull_vol] = convhulln(a594_clust1_dot_coord); % Convex hull volume of cluster 1
                [~,a594_clust2_hull_vol] = convhulln(a594_clust2_dot_coord); % Convex hull volume of cluster 2
                a594_delta_clust_vol(a594_seg_nuc_2clust_num,1) = abs(a594_clust1_hull_vol - a594_clust2_hull_vol) / max(a594_clust1_hull_vol, a594_clust2_hull_vol); % Relative absolute difference in convex hull volume
                a594_seg_nuc_2clust_num = a594_seg_nuc_2clust_num + 1;
            end
        end

    end

    %A647 dots
    if seg_nuc_data.a647_dot_counts(i) > 0 % Check if i-th nucleus contains dots in A647
        a647_seg_nuc_clust_num(i,1) = max(seg_nuc_data.a647_cluster_id(seg_nuc_data.a647_nuc_id == i)); % # of A647 clusters in i-th nucleus

        % Calculate convex hull volume of clusters with > 3 dots in each channel
        if a647_seg_nuc_clust_num(i,1) > 0
            for j = 1:a647_seg_nuc_clust_num(i,1)
                a647_dot_in_clust_coord = seg_nuc_data.a647_dot_coord(seg_nuc_data.a647_nuc_id == i & seg_nuc_data.a647_cluster_id == j,1:3);
                if height(a647_dot_in_clust_coord) > 3
                    [~,a647_clust_hull_vol(a647_clust_num,1)] = convhulln(a647_dot_in_clust_coord); % Calculate convex hull volume
                    a647_clust_num = a647_clust_num + 1;
                end
            end
        end

        % Calculate difference in convex hull vol between clusters for nuclei with 2 clusters
        if a647_seg_nuc_clust_num(i,1) == 2
            a647_clust1_dot_coord = seg_nuc_data.a647_dot_coord(seg_nuc_data.a647_nuc_id == i & seg_nuc_data.a647_cluster_id == 1,1:3);
            a647_clust2_dot_coord = seg_nuc_data.a647_dot_coord(seg_nuc_data.a647_nuc_id == i & seg_nuc_data.a647_cluster_id == 2,1:3);
            if height(a647_clust1_dot_coord) > 3 && height(a647_clust2_dot_coord) > 3
                [~,a647_clust1_hull_vol] = convhulln(a647_clust1_dot_coord); % Convex hull volume of cluster 1
                [~,a647_clust2_hull_vol] = convhulln(a647_clust2_dot_coord); % Convex hull volume of cluster 2
                a647_delta_clust_vol(a647_seg_nuc_2clust_num,1) = abs(a647_clust1_hull_vol - a647_clust2_hull_vol) / max(a647_clust1_hull_vol, a647_clust2_hull_vol); % Relative absolute difference in convex hull volume
                a647_seg_nuc_2clust_num = a647_seg_nuc_2clust_num + 1;
            end
        end
    end

end

%A594 dots
% Plot histogram of number of A594 clusters per nucleus
figure(1);
histogram(a594_seg_nuc_clust_num, 'BinMethod', 'integers', 'FaceColor', [0.7 0.7 0.7], 'Normalization', 'probability');
xlabel('# of clusters per nucleus');
ylabel('Relative Frequency');
text('Position', [0.95, 0.95], 'String', sprintf('n = %d', numel(a594_seg_nuc_clust_num)), ...
    'Units', 'normalized', 'HorizontalAlignment', 'right', 'VerticalAlignment', 'top', 'FontSize', 10, 'FontWeight', 'bold');
print(figure(1), fullfile(store_figs_dir, [dataset_name, '__a594_clusters_per_nucleus_histogram']), '-dpdf');  % Save figure as PDF

% Plot boxplot of convex hull volumes of A594 clusters
figure(2);
