xlabel('Cluster Hull Volume (um^3)');
ylabel('Frequency');
median_volume = nanmedian(a594_clust_hull_vol);
num_clusters = sum(~isnan(a594_clust_hull_vol));
text(1, median_volume, sprintf('Median: %.4f\nN: %d', median_volume, num_clusters), ...
