print(figure(2), fullfile(store_figs_dir, [dataset_name, '__a594_cluster_vol_boxplot']), '-dpdf');  % Save figure as PDF

% Plot boxplot of relative absolute differences in convex hull volume for nuclei with 2 A594 clusters
