print(figure(4), fullfile(store_figs_dir, [dataset_name, '__a647_clusters_per_nucleus_histogram']), '-dpdf');  % Save figure as PDF

% Plot boxplot of convex hull volumes of A647 clusters
figure(5);
boxplot(a647_clust_hull_vol, 'OutlierSize', 3, 'Symbol', 'o', 'Color', [0.5 0.5 0.5], 'Jitter', 0.5);
xlabel('Cluster Hull Volume (um^3)');
ylabel('Frequency');
median_volume = nanmedian(a647_clust_hull_vol);
num_clusters = sum(~isnan(a647_clust_hull_vol));
text(1, median_volume, sprintf('Median: %.4f\nN: %d', median_volume, num_clusters), ...
