%% Calculate and plot various properties of chr17 CTs for iiXZ1081 dataset

clear all

%Specify dataset to analyse
dataset_name = 'iiXZ1081_20241128_002_dw_A594_cwdots_clusters_20251022';

%Specify folder where figures should be stored
store_figs_dir = '/Users/nicolacrosetto/Library/CloudStorage/OneDrive-KarolinskaInstitutet/KI/Manuscripts/Li Wang et al_FOLD-FISH/FIRST SUBMISSION/Analyses/Image analyses/Plots/Chr17 territories';

% Load the .mat files with info about chr17 clusters
parsed_data_dir = '/Users/nicolacrosetto/Library/CloudStorage/OneDrive-KarolinskaInstitutet/KI/Manuscripts/Li Wang et al_FOLD-FISH/FIRST SUBMISSION/Analyses/Image analyses/Parsed datasets';
load([parsed_data_dir, '/', dataset_name, '__seg_nuc_data.mat']);

seg_nuc_num = seg_nuc_data.seg_nuc_num; % # of segmented nuclei with dots in either A594 or A647 or both channels

clust_num = 1; % Counter of clusters
min4dots_clust_num = 1; % Counter of clusters with at least 3 dots (min required to calculate a 3D convex hull)
seg_nuc_2clust_num = 1; % Counter of nuclei with 2 clusters with at least 3 dots


%Loop through nuclei, count number of clusters and calculate convex hull volume of each cluster in each channel
for i= 1:seg_nuc_num
    
    seg_nuc_clust_num(i,1) = max(seg_nuc_data.cluster_id(seg_nuc_data.nuc_id == i)); % # of clusters in i-th nucleus

    %Calculate convex hull volume of clusters with at least 4 dots
    if seg_nuc_clust_num(i,1) > 0
        for j = 1:seg_nuc_clust_num(i,1)
            dot_in_clust_coord = seg_nuc_data.dot_coord(seg_nuc_data.nuc_id == i & seg_nuc_data.cluster_id == j,1:3);
            dot_in_clust_num(clust_num, 1) = height(dot_in_clust_coord);
            if dot_in_clust_num(clust_num, 1) > 3
                [~,clust_hull_vol(min4dots_clust_num,1)] = convhulln(dot_in_clust_coord); % Calculate convex hull volume
                min4dot_in_clust_num(min4dots_clust_num,1) = dot_in_clust_num(clust_num, 1);
                min4dots_clust_num = min4dots_clust_num + 1;
            end
            clust_num = clust_num + 1;
        end
    end

    %Calculate difference in convex hull vol between clusters for nuclei with 2 clusters with at least 4 dots
    if seg_nuc_clust_num(i,1) == 2
        clust1_dot_coord = seg_nuc_data.dot_coord(seg_nuc_data.nuc_id == i & seg_nuc_data.cluster_id == 1,1:3);
        clust2_dot_coord = seg_nuc_data.dot_coord(seg_nuc_data.nuc_id == i & seg_nuc_data.cluster_id == 2,1:3);
        if height(clust1_dot_coord) > 3 && height(clust2_dot_coord) > 3
            [~,clust1_hull_vol(seg_nuc_2clust_num,1)] = convhulln(clust1_dot_coord); % Convex hull volume of cluster 1
            [~,clust2_hull_vol(seg_nuc_2clust_num,1)] = convhulln(clust2_dot_coord); % Convex hull volume of cluster 2
            delta_clust_vol(seg_nuc_2clust_num,1) = abs(clust1_hull_vol(seg_nuc_2clust_num,1) - clust2_hull_vol(seg_nuc_2clust_num,1)) / ...
                                                    max(clust1_hull_vol(seg_nuc_2clust_num,1), clust2_hull_vol(seg_nuc_2clust_num,1)); % Relative absolute difference in convex hull volume
            seg_nuc_2clust_num = seg_nuc_2clust_num + 1;
        end
    end

end

