%% Calculate pairwise distances between chr17 p- and q-arm CTs for iiXZ1126 dataset

clear all

%Specify dataset to analyse
dataset_name = 'iiXZ1126_20250210_002_dw_A594_A647_cwdots_clusters_20251013';

%Specify folder where figures should be stored
store_figs_dir = '/Users/nicolacrosetto/Library/CloudStorage/OneDrive-KarolinskaInstitutet/KI/Manuscripts/Li Wang et al_FOLD-FISH/FIRST SUBMISSION/Analyses/Image analyses/Plots/Chr17 territories';

% Load the .mat files with info about chr17 clusters
parsed_data_dir = '/Users/nicolacrosetto/Library/CloudStorage/OneDrive-KarolinskaInstitutet/KI/Manuscripts/Li Wang et al_FOLD-FISH/FIRST SUBMISSION/Analyses/Image analyses/Parsed datasets';
load([parsed_data_dir, '/', dataset_name, '__seg_nuc_data.mat']);

seg_nuc_num = seg_nuc_data.seg_nuc_num; % # of segmented nuclei with dots in either A594 or A647 or both channels

n = 1; %Counter of nuclei with 2 clusters in A594 and 2 in A647 and at least 2 dots per cluster
all_a594_intra_clust_pdist = [];
all_a647_intra_clust_pdist = [];

%Loop through nuclei, count number of clusters and calculate pairwise distances between clusters for cells with 2 A594 and 2 A647 clusters
for i= 1:seg_nuc_num
    
    if seg_nuc_data.a594_dot_counts(i) > 0 && seg_nuc_data.a647_dot_counts(i) > 0 %Check if i-th nucleus contains dots in A594 and A647
        a594_seg_nuc_clust_num(i,1) = max(seg_nuc_data.a594_cluster_id(seg_nuc_data.a594_nuc_id == i)); % # of A594 clusters in i-th nucleus
        a647_seg_nuc_clust_num(i,1) = max(seg_nuc_data.a647_cluster_id(seg_nuc_data.a647_nuc_id == i)); % # of A647 clusters in i-th nucleus
        
        %Calculate pairwise distances within and between clusters for nuclei with 2 clusters
        if a594_seg_nuc_clust_num(i,1) == 2 && a647_seg_nuc_clust_num(i,1) == 2
            
            %Extract dot coord in each cluster
            a594_clust1_dot_coord = seg_nuc_data.a594_dot_coord(seg_nuc_data.a594_nuc_id == i & seg_nuc_data.a594_cluster_id == 1,1:3);
            a594_clust2_dot_coord = seg_nuc_data.a594_dot_coord(seg_nuc_data.a594_nuc_id == i & seg_nuc_data.a594_cluster_id == 2,1:3);          
            a647_clust1_dot_coord = seg_nuc_data.a647_dot_coord(seg_nuc_data.a647_nuc_id == i & seg_nuc_data.a647_cluster_id == 1,1:3);
            a647_clust2_dot_coord = seg_nuc_data.a647_dot_coord(seg_nuc_data.a647_nuc_id == i & seg_nuc_data.a647_cluster_id == 2,1:3);

            %Check that each cluster contains at least 2 dots
            if height(a594_clust1_dot_coord)>1 && height(a594_clust2_dot_coord)>1 && height(a647_clust1_dot_coord)>1 && height(a647_clust2_dot_coord)>1

                %Calculate centroid coord in each cluster
                a594_clust1_centroid_coord = mean(a594_clust1_dot_coord);
                a594_clust2_centroid_coord = mean(a594_clust2_dot_coord);
                a647_clust1_centroid_coord = mean(a647_clust1_dot_coord);
                a647_clust2_centroid_coord = mean(a647_clust2_dot_coord);

                %Calculate intra-cluster pdist
                a594_pdist = vertcat(pdist(a594_clust1_dot_coord)', pdist(a594_clust2_dot_coord)');
                a647_pdist = vertcat(pdist(a647_clust1_dot_coord)', pdist(a647_clust2_dot_coord)');
                mean_a594_pdist(n,1) = mean(a594_pdist);
                mean_a647_pdist(n,1) = mean(a647_pdist);
                all_a594_intra_clust_pdist = vertcat(all_a594_intra_clust_pdist,a594_pdist);
                all_a647_intra_clust_pdist = vertcat(all_a647_intra_clust_pdist, a647_pdist);

                %Calculate inter-centroid dist
                a594_inter_centroid_dist(n,1) = pdist2(a594_clust1_centroid_coord,a594_clust2_centroid_coord);
                a647_inter_centroid_dist(n,1) = pdist2(a647_clust1_centroid_coord,a647_clust2_centroid_coord);
                min_a594_a647_inter_centroid_dist(n,1) = min(vertcat(pdist2(a594_clust1_centroid_coord,a647_clust1_centroid_coord),...
                    pdist2(a594_clust1_centroid_coord,a647_clust2_centroid_coord),...
                    pdist2(a594_clust2_centroid_coord,a647_clust1_centroid_coord),...
                    pdist2(a594_clust2_centroid_coord,a647_clust2_centroid_coord)));

                n = n + 1; % Increment counter of nuclei with 2 clusters in A594 and 2 in A647

            end
            
        end

    end

end

% Plot dot plots of intra- and inter-cluster distances
figure(1);
subplot(3, 2, 1);
scatter(0.8 + 0.4 * rand(size(mean_a594_pdist)), mean_a594_pdist, 'filled', 'MarkerFaceColor', [0.7 0.7 0.7], 'SizeData', 7); % Make dots smaller
xlim([0 2]); % Set x-axis limits
ylabel('A594 Pairwise Distance');
text('Position', [0.95, 0.95], 'String', sprintf('n = %d\nMedian: %.4f', numel(mean_a594_pdist), nanmedian(mean_a594_pdist)), ...
    'Units', 'normalized', 'HorizontalAlignment', 'right', 'VerticalAlignment', 'top', 'FontSize', 10, 'FontWeight', 'bold');
