xlim([0 2]); % Set x-axis limits
ylabel('A647 Pairwise Distance');
text('Position', [0.95, 0.95], 'String', sprintf('n = %d\nMedian: %.4f', numel(mean_a647_pdist), nanmedian(mean_a647_pdist)), ...
    'Units', 'normalized', 'HorizontalAlignment', 'right', 'VerticalAlignment', 'top', 'FontSize', 10, 'FontWeight', 'bold');
hold on;
yline(nanmedian(mean_a647_pdist), 'r--', 'Median', 'LabelHorizontalAlignment', 'left'); % Add median line
hold off;

subplot(3, 2, 3);
scatter(0.8 + 0.4 * rand(size(a594_inter_centroid_dist)), a594_inter_centroid_dist, 'filled', 'MarkerFaceColor', [0.7 0.7 0.7], 'SizeData', 7); % Make dots smaller
xlim([0 2]); % Set x-axis limits
ylabel('A594 Inter-Centroid Distance');
text('Position', [0.95, 0.95], 'String', sprintf('n = %d\nMedian: %.4f', numel(a594_inter_centroid_dist), nanmedian(a594_inter_centroid_dist)), ...
    'Units', 'normalized', 'HorizontalAlignment', 'right', 'VerticalAlignment', 'top', 'FontSize', 10, 'FontWeight', 'bold');
hold on;
yline(nanmedian(a594_inter_centroid_dist), 'r--', 'Median', 'LabelHorizontalAlignment', 'left'); % Add median line
hold off;

subplot(3, 2, 4);
scatter(0.8 + 0.4 * rand(size(a647_inter_centroid_dist)), a647_inter_centroid_dist, 'filled', 'MarkerFaceColor', [0.7 0.7 0.7], 'SizeData', 7); % Make dots smaller
xlim([0 2]); % Set x-axis limits
ylabel('A647 Inter-Centroid Distance');
text('Position', [0.95, 0.95], 'String', sprintf('n = %d\nMedian: %.4f', numel(a647_inter_centroid_dist), nanmedian(a647_inter_centroid_dist)), ...
    'Units', 'normalized', 'HorizontalAlignment', 'right', 'VerticalAlignment', 'top', 'FontSize', 10, 'FontWeight', 'bold');
