xlim([0 2]); % Set x-axis limits
ylabel('Min A647-A594 Inter-Centroid Distance');
text('Position', [0.95, 0.95], 'String', sprintf('n = %d\nMedian: %.4f', numel(min_a594_a647_inter_centroid_dist), nanmedian(min_a594_a647_inter_centroid_dist)), ...
    'Units', 'normalized', 'HorizontalAlignment', 'right', 'VerticalAlignment', 'top', 'FontSize', 10, 'FontWeight', 'bold');
hold on;
